# Python with Flask
@app.get("/projects/<int:project_id>")
def get_project(project_id):
    project = service.find(project_id)
    if project is None:
        return {"title": "Project not found", "status": 404}, 404
    return jsonify(project), 200, {"Cache-Control": "max-age=60"}
